<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount,computed,nextTick,watch} from 'vue'
import {Sparkles,ShieldCheck,ArrowRight,Check,AlertCircle} from '@lucide/vue'
import InfoTip from './InfoTip.vue'
import EvidenceDetails from './EvidenceDetails.vue'
import type {AISettings,AIQuote,AIRecord,AIRecent,AILimits,AIEvidence} from '../ai-types'
const props=defineProps<{window?:{start_ms:number;end_ms:number}}>()
const settings=ref<AISettings|null>(null),quote=ref<AIQuote|null>(null),record=ref<AIRecord|null>(null),recent=ref<AIRecent[]>([])
const hoursPerDay=ref(24),totalBudget=ref(0)
const question=ref('Com os dados que temos, qual seria o meu custo mensal de energia?'),error=ref(''),notice=ref(''),busy=ref(''),key=ref('')
const limits=ref<AILimits>({enabled:true,per_analysis_usd:.05,daily_usd:1,monthly_usd:2})
const evidence=ref<AIEvidence[]>([]),evidenceClaim=ref(''),evidenceArea=ref<HTMLElement>()
let timer:ReturnType<typeof setTimeout>|undefined,disposed=false
const running=computed(()=>record.value?.state==='running')
const supportingClaims=computed(()=>record.value?.report?.claims.filter(c=>c.id!==record.value?.report?.answer?.id)||[])
const validHours=computed(()=>Number.isFinite(hoursPerDay.value)&&hoursPerDay.value>0&&hoursPerDay.value<=24)
watch(()=>props.window,()=>{quote.value=null},{deep:true})
const usd=(n:number|undefined,d=4)=>n===undefined?'—':`US$ ${n.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:d})}`
const when=(n:number)=>new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit',timeZone:'America/Sao_Paulo'}).format(n)
const states:Record<string,string>={quoted:'Prévia preparada',running:'Analisando',complete:'Concluída',failed:'Bloqueada',interrupted:'Interrompida'}
async function api<T>(path:string,options:RequestInit={}):Promise<T>{const response=await fetch(path,{...options,headers:{'Content-Type':'application/json',...options.headers}});if(!response.ok){const body=await response.json().catch(()=>({}));throw new Error(typeof body.detail==='string'?body.detail:'Não foi possível concluir a operação.')};return response.json()}
async function load(){const [s,h]=await Promise.all([api<AISettings>('/api/ai/settings'),api<{analyses:AIRecent[]}>('/api/ai/analyses')]);settings.value=s;limits.value={...s.limits};totalBudget.value=s.authorized_total_usd;recent.value=h.analyses}
async function prepare(){busy.value='quote';error.value='';notice.value='';evidence.value=[];try{if(!props.window)throw new Error('Selecione um período com dados.');quote.value=await api<AIQuote>('/api/ai/quotes',{method:'POST',body:JSON.stringify({...props.window,question:question.value,hours_per_day:hoursPerDay.value})})}catch(e){error.value=(e as Error).message}finally{busy.value=''}}
async function readRecord(id:string){clearTimeout(timer);try{const item=await api<AIRecord>('/api/ai/analyses/'+encodeURIComponent(id));if(disposed)return;record.value=item;if(item.state==='running'){timer=setTimeout(()=>readRecord(id),1500)}else{busy.value='';await load()}}catch(e){if(!disposed){error.value=(e as Error).message;busy.value=''}}}
async function start(){if(!quote.value)return;busy.value='analysis';error.value='';evidence.value=[];try{const id=quote.value.id;if(quote.value.cached){notice.value='Análise salva reutilizada, sem nova chamada à API.'}else{await api('/api/ai/analyses/'+id,{method:'POST'})};quote.value=null;await readRecord(id)}catch(e){error.value=(e as Error).message;busy.value='';await load()}}
async function saveLimits(){busy.value='limits';error.value='';notice.value='';try{await api('/api/ai/settings',{method:'PUT',body:JSON.stringify({...limits.value,authorized_total_usd:totalBudget.value})});quote.value=null;await load();notice.value='Limites salvos. Pausar bloqueia novas chamadas; uma chamada já enviada pode ter custo.'}catch(e){error.value=(e as Error).message}finally{busy.value=''}}
async function removeKey(){busy.value='key';error.value='';try{await api('/api/ai/key',{method:'DELETE'});key.value='';await load();notice.value='Chave removida e chamadas pausadas. Revogue a credencial no provedor se necessário.'}catch(e){error.value=(e as Error).message}finally{busy.value=''}}
async function saveKey(){busy.value='key';error.value='';try{await api('/api/ai/key',{method:'PUT',body:JSON.stringify({key:key.value})});key.value='';await load();notice.value='Chave atualizada no armazenamento privado deste PC.'}catch(e){error.value=(e as Error).message}finally{busy.value=''}}
async function showEvidence(ids:string[],text:string){evidenceClaim.value=text;evidence.value=ids.flatMap(id=>record.value?.report?.evidence[id]?[record.value.report.evidence[id]!]:[]);await nextTick();evidenceArea.value?.focus({preventScroll:true});evidenceArea.value?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})}
function preset(text:string){question.value=text;quote.value=null}
onMounted(async()=>{try{await load();const active=recent.value.find(r=>r.state==='running');if(active)await readRecord(active.id)}catch(e){error.value=(e as Error).message}})
onBeforeUnmount(()=>{disposed=true;clearTimeout(timer)})
</script>
<template>
<div class="ai-layout">
<div class="ai-main">
  <div v-if="error" class="banner error" role="alert"><AlertCircle :size="18"/><span>{{error}}</span></div>
  <div v-if="notice" class="banner success" role="status"><Check :size="18"/><span>{{notice}}</span></div>
  <section class="ai-compose" aria-labelledby="ai-question-heading">
    <div class="section-heading"><h2 id="ai-question-heading">Investigar o período</h2><InfoTip label="Como a análise é validada">A IA escolhe consultas e a resposta mais relevante para sua pergunta. A aplicação calcula os valores e só exibe afirmações ligadas a evidências registradas. Nenhum ajuste no coletor é aplicado pela IA.</InfoTip></div>
    <label class="ai-question-label" for="ai-question">O que você quer investigar?</label>
    <textarea id="ai-question" v-model="question" rows="3" maxlength="500" :disabled="running" @input="quote=null"/>
    <div class="ai-presets"><button class="button small" :disabled="running" @click="preset('Quais aplicativos coincidem com os picos de potência da CPU e da GPU? Compare os intervalos sem atribuir causa.')">Aplicativos e picos</button><button class="button small" :disabled="running" @click="preset('Com os dados que temos, qual seria o meu custo mensal de energia?')">Custo mensal</button><button class="button small" :disabled="running" @click="preset('Analise a energia e o custo reportados, respeitando cobertura, vigências e alcance dos sensores.')">Energia e custo</button><button class="button small" :disabled="running" @click="preset('Compare a potência e o uso entre períodos e procure desvios relevantes. Não atribua uma causa sem evidência.')">Variações de carga</button><button class="button small" :disabled="running" @click="preset('Inspecione a qualidade e as limitações dos dados. Que coleta adicional seria útil para investigar picos por aplicativo?')">Qualidade e próximos dados</button></div>
    <div class="ai-scenario"><label for="ai-daily-hours">Uso diário para projeções</label><input id="ai-daily-hours" aria-describedby="ai-hours-hint" v-model.number="hoursPerDay" type="number" min="0.1" max="24" step="0.1" :disabled="running" @input="quote=null"><span id="ai-hours-hint">horas por dia · mês de 30 dias</span><InfoTip label="Sobre as horas de uso">É uma hipótese ajustável, não uma rotina detectada. A projeção repete a carga média dos intervalos válidos por essas horas; o restante do dia fica fora da conta. Uma duração explícita, como “8 horas por dia”, na pergunta tem prioridade e aparece na prévia.</InfoTip></div>
    <p v-if="!validHours" class="field-hint">Informe mais de zero e até 24 horas por dia.</p>
    <div class="ai-action-row"><span class="muted">GPT-5.4 mini · até {{usd(settings?.limits.per_analysis_usd)}} por análise</span><button class="button primary" :disabled="!!busy||running||!settings?.key_configured||!settings?.limits.enabled||!settings?.remaining_usd||!window||!question.trim()||!validHours" @click="prepare"><Sparkles :size="16"/>{{busy==='quote'?'Preparando…':'Preparar análise'}}</button></div>
    <div v-if="quote" class="ai-quote" role="region" aria-label="Prévia da análise"><div><strong>{{when(quote.window.start_ms)}} até {{when(quote.window.end_ms)}}</strong><p>{{quote.sample_count.toLocaleString('pt-BR')}} amostras · {{quote.cached?'Reutilização sem nova chamada:':'teto desta análise:'}} {{usd(quote.maximum_usd)}}.</p><p v-if="quote.projection">Cenário mensal: {{quote.projection.hours_per_day.toLocaleString('pt-BR')}} h/dia × 30 dias{{quote.projection.hours_origin==='question'?', conforme a pergunta':''}}.</p></div><div v-if="quote.calculation_preview" class="ai-local-preview"><h3>Projeção calculada sem IA</h3><p>{{quote.calculation_preview.text}}</p><p>{{quote.calculation_preview.caveats[0]}}</p><details><summary>Como foi calculada?</summary><p>Energia de cada componente ÷ horas com leituras válidas × horas por dia × 30 dias × tarifa do fim do período.</p><ul><li v-for="item in quote.calculation_preview.assumptions" :key="item">{{item}}</li><li v-for="item in quote.calculation_preview.caveats.slice(1)" :key="item">{{item}}</li></ul></details><p class="muted">Esse cálculo não gasta créditos. A análise com IA abaixo pode investigar variações e consultar outros dados do período.</p></div><details><summary>Quais dados serão enviados?</summary><ul><li v-for="item in quote.data_sent" :key="item">{{item}}</li></ul><p class="muted">Sem identificação do PC, credenciais ou rótulos brutos. O provedor pode reter registros de monitoramento de abuso.</p></details><button class="button primary" :disabled="!!busy||running" @click="start">{{quote.cached?'Ver análise salva':'Analisar por até '+usd(quote.maximum_usd)}}<ArrowRight :size="16"/></button></div>
    <p v-if="settings&&!settings.key_configured" class="field-hint">Configure a chave da API na seção de credencial para começar.</p>
    <p v-if="settings&&!settings.limits.enabled" class="field-hint">Chamadas pausadas nos limites de gasto.</p>
  </section>
  <div v-if="running" class="ai-running" role="status"><Sparkles :size="20"/><div><strong>Consultando e conferindo as evidências…</strong><p>A resposta aparece depois da conferência dos cálculos e das referências. Reabrir esta tela acompanha a mesma execução.</p></div></div>
  <section v-if="record&&record.state!=='running'" class="ai-result" aria-labelledby="ai-result-heading">
    <div class="section-heading"><h2 id="ai-result-heading">{{record.state==='complete'?'Resposta à sua pergunta':'Análise não exibida'}}</h2><span :class="['status-badge',record.state==='complete'?'positive':'warning']">{{states[record.state]||record.state}}</span></div>
    <div class="ai-result-meta"><span>{{when(record.created_ms)}}</span><span>Custo da análise: {{usd(record.estimated_cost_usd,6)}}</span><span v-if="record.report">{{record.report.elapsed_seconds.toLocaleString('pt-BR',{maximumFractionDigits:1})}} s</span></div>
    <p v-if="record.error" class="ai-blocked" role="alert">{{record.error}}</p>
    <template v-if="record.report">
      <p class="ai-period">{{when(record.report.window.start_ms)}} até {{when(record.report.window.end_ms)}} · componentes reportados</p>
      <p class="ai-answered-question">{{record.question}}</p>
      <div v-if="record.report.answer" class="ai-answer">
        <span v-if="record.report.answer.kind==='monthly_projection'" class="status-badge warning">Projeção condicional · componentes</span>
        <span v-if="record.report.answer.kind==='process_coincidence'" class="status-badge warning">Coincidência temporal</span>
        <p class="ai-answer-text">{{record.report.answer.text}}</p>
        <p v-for="item in record.report.answer.caveats.slice(0,1)" :key="item" class="ai-answer-scope">{{item}}</p>
        <button class="ai-evidence-button" @click="showEvidence(record.report.answer.evidence_ids,record.report.answer.text)">Conferir cálculo e dados<ArrowRight :size="13"/></button>
        <details v-if="record.report.answer.assumptions.length||record.report.answer.caveats.length" class="ai-answer-assumptions"><summary>Premissas e limites da resposta</summary><ul><li v-for="item in [...record.report.answer.assumptions,...record.report.answer.caveats.slice(1)]" :key="item">{{item}}</li></ul></details>
        <p v-if="record.report.answer_status==='insufficient'" class="field-hint">Falta informação para completar o cálculo. A resposta acima indica o que está disponível.</p>
      </div>
      <p v-else class="muted">Esta análise foi salva no formato anterior, com dados de apoio separados. Prepare uma nova análise para obter uma resposta principal e projeções.</p>
      <details v-if="supportingClaims.length" class="ai-support" :open="!record.report.answer"><summary>Dados de apoio ({{supportingClaims.length}})</summary><p class="muted">Leituras, cobertura e comparações usadas na investigação.</p>
        <article v-for="(claim,index) in supportingClaims" :key="claim.id" class="ai-claim"><Check :size="17" class="positive-text"/><div><p>{{claim.text}}</p><button class="ai-evidence-button" :aria-label="`Ver evidências da afirmação ${index+1}`" @click="showEvidence(claim.evidence_ids,claim.text)">Ver evidências<ArrowRight :size="13"/></button></div></article>
      </details>
      <div v-if="record.report.recommendations.length" class="ai-suggestions"><h3>Próximos passos sugeridos</h3><article v-for="(item,index) in record.report.recommendations" :key="item.id"><p>{{item.text}}</p><button class="ai-evidence-button" :aria-label="`Ver evidências da sugestão ${index+1}`" @click="showEvidence(item.evidence_ids,item.text)">Ver justificativa<ArrowRight :size="13"/></button></article><small>Sugestões não alteram o coletor.</small></div>
      <details class="ai-limitations"><summary>Alcance e limitações</summary><ul><li v-for="item in record.report.limitations" :key="item">{{item}}</li></ul><p class="muted">A aplicação confere os cálculos e as referências. A IA escolhe as consultas e a resposta; isso não comprova a calibração dos sensores nem a representatividade do período.</p></details>
    </template>
  </section>
  <section v-if="evidence.length" ref="evidenceArea" tabindex="-1" class="ai-evidence-area" aria-labelledby="ai-evidence-heading"><h2 id="ai-evidence-heading">Evidências da afirmação</h2><p class="ai-selected-claim">{{evidenceClaim}}</p><EvidenceDetails v-for="item in evidence" :key="item.id" :evidence="item" :analysis-id="record?.id"/></section>
</div>
<aside class="ai-sidebar" aria-label="Gastos e histórico de IA">
  <section class="ai-budget"><div class="section-heading"><h2>Gastos e limites</h2><InfoTip label="Sobre o controle de gastos">Valores em dólares, estimados pelos tokens com tarifa cheia. Reservas de chamadas incertas continuam no limite. O limite acumulado inclui somente as chamadas registradas nesta instalação, inclusive reservas incertas. Alterar o limite não apaga gastos anteriores nem limita outras aplicações da conta.</InfoTip></div><p class="ai-budget-value">{{usd(settings?.usage.total_usd)}} <span>de {{usd(settings?.authorized_total_usd,2)}}</span></p><p class="muted">Hoje: {{usd(settings?.usage.daily_usd)}} de {{usd(settings?.limits.daily_usd,2)}}.</p><p class="muted">Disponível nos limites atuais: {{usd(settings?.remaining_usd)}}.</p><p v-if="settings?.usage.pending_usd" class="field-hint">{{usd(settings.usage.pending_usd)}} em reservas incertas.</p>
    <details class="ai-budget-edit"><summary>Ajustar limites e pausar</summary><form @submit.prevent="saveLimits"><label class="check-row"><input v-model="limits.enabled" type="checkbox">Permitir novas chamadas</label><label>Limite acumulado (US$)<input v-model.number="totalBudget" type="number" min="0" max="1000" step=".001" required></label><label>Por análise (US$)<input v-model.number="limits.per_analysis_usd" type="number" min=".001" :max="Math.min(totalBudget||5,5)" step=".001" required></label><label>Por dia (US$)<input v-model.number="limits.daily_usd" type="number" min=".001" :max="totalBudget||1000" step=".001" required></label><label>Por mês (US$)<input v-model.number="limits.monthly_usd" type="number" min=".001" :max="totalBudget||1000" step=".001" required></label><p class="muted">Novo uso começa sem orçamento aprovado. Escolha o limite acumulado e permita chamadas para ativar. Dia e mês no horário de Brasília.</p><button class="button" type="submit" :disabled="!!busy">Salvar limites</button></form></details>
    <details class="ai-key"><summary>Credencial da API</summary><p class="muted">{{settings?.key_configured?'Chave configurada em arquivo privado.':'Nenhuma chave configurada.'}}</p><form @submit.prevent="saveKey"><label>Nova chave da API<input v-model="key" type="password" autocomplete="off" spellcheck="false" minlength="10" maxlength="1024" required></label><button class="button" type="submit" :disabled="!key||!!busy">Salvar chave</button></form><button v-if="settings?.key_configured" class="text-button" :disabled="!!busy||running" @click="removeKey">Remover chave deste PC e pausar</button><p class="field-hint">Remover não apaga cópias em backups nem revoga a chave no provedor.</p></details>
  </section>
  <section class="ai-history"><h2>Análises recentes</h2><p v-if="!recent.filter(r=>r.state!=='quoted').length" class="muted">As análises concluídas e suas evidências ficam salvas neste PC.</p><button v-for="item in recent.filter(r=>r.state!=='quoted')" :key="item.id" class="ai-history-item" :disabled="running" @click="evidence=[];error='';readRecord(item.id)"><span>{{when(item.created_ms)}}<small class="ai-history-question">{{item.question}}</small><small>{{states[item.state]||item.state}}</small></span><ArrowRight :size="14"/></button></section>
  <p class="ai-privacy"><ShieldCheck :size="16"/>A coleta continua local. Uma análise solicitada envia sua pergunta e recortes à API. Evite dados pessoais e credenciais no texto.</p>
</aside>
</div>
</template>
